// HTML renders an icon exactly as @patternfly/react-icons did, with class
// and style added to the svg when they are not empty. An unknown name
// renders as an HTML comment saying so.
func HTML(name, class, style string) template.HTML {
	ic, ok := Icons[name]
	if !ok {
		return template.HTML(fmt.Sprintf("<!-- missing icon %s -->", name))
	}
	cls := "pf-v6-svg"
	if class != "" {
		cls += " " + template.HTMLEscapeString(class)
	}
	st := ""
	if style != "" {
		st = fmt.Sprintf(` style="%s"`, template.HTMLEscapeString(style))
	}
	return template.HTML(fmt.Sprintf(`<svg class="%s" fill="currentColor" viewBox="%d %d %d %d" aria-hidden="true" role="img" width="1em" height="1em"%s><path d="%s"></path></svg>`, cls, ic.X, ic.Y, ic.W, ic.H, st, ic.D))
}
